package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.JwksJsonVO;

class JwksJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of jwks json of oauth client")
  void test_jwks_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    JwksJsonValueHolder<Object> value = new JwksJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.jwksJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getJwksJsonValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getJwksJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.jwksJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getJwksJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getJwksJson().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of jwks json of oauth client")
  void test_jwks_json_value_holder_assign_value_object() {
    Object holder = new Object();
    JwksJsonValueHolder<Object> value = new JwksJsonValueHolder<>(holder);
    JwksJsonVO vo = JwksJsonVO.from("one");
    Assertions.assertFalse(value.getJwksJsonValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.jwksJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getJwksJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.jwksJson(Optional.empty()));
    Assertions.assertFalse(value.getJwksJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.jwksJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getJwksJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of jwks json of oauth client against the original")
  void test_jwks_json_value_holder_read() {
    Object holder = new Object();
    JwksJsonValueHolder<Object> value = new JwksJsonValueHolder<>(holder);
    JwksJsonVO vo = JwksJsonVO.from("one");
    JwksJsonVO other = JwksJsonVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getJwksJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readJwksJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readJwksJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.jwksJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readJwksJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readJwksJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of jwks json of oauth client")
  void test_jwks_json_value_holder_unset() {
    Object holder = new Object();
    JwksJsonValueHolder<Object> value = new JwksJsonValueHolder<>(holder);
    JwksJsonVO vo = JwksJsonVO.from("one");
    value.jwksJson(vo);
    Assertions.assertSame(holder, value.unsetJwksJsonIfMatches("jwksJson_other"));
    Assertions.assertTrue(value.getJwksJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetJwksJsonIfMatches("jwksJson"));
    Assertions.assertFalse(value.getJwksJsonValue().isPresent(),
        "The field name must clear the value");
    value.jwksJson(vo);
    Assertions.assertSame(holder, value.unsetJwksJson());
    Assertions.assertFalse(value.getJwksJsonValue().isPresent(), "Unset must clear the value");
  }
}
